[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ScreenVault — UI & UX design inspiration for mobile & web apps</title>
<meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary-dark: #141414;
  --bg-white: #FFFFFF;
  --surface-gray: #F5F5F5;
  --mid-gray: #E5E5E5;
  --text-secondary: #6B6B6B;
  --text-tertiary: #999999;
  --accent: #6C5CE7;
  --accent-hover: #5A4BD1;
  --accent-light: rgba(108, 92, 231, 0.08);
  --accent-light-2: rgba(108, 92, 231, 0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-pill: 100px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--primary-dark);
  background: var(--bg-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--primary-dark);
  color: #fff;
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.announcement-bar span { color: var(--accent); }

/* ===== HEADER / NAV ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--mid-gray);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.logo {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.03em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-icon {
  width: 28px;
  height: 28px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-icon svg { width: 16px; height: 16px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--primary-dark); }
.nav-cta {
  background: var(--primary-dark) !important;
  color: #fff !important;
  padding: 8px 20px;
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-weight: 600;
  transition: opacity var(--transition);
}
.nav-cta:hover { opacity: 0.85; }
.mobile-menu-btn { display: none; width: 24px; height: 24px; flex-direction: column; justify-content: center; gap: 5px; }
.mobile-menu-btn span { display: block; height: 2px; background: var(--primary-dark); border-radius: 2px; transition: var(--transition); }
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255,255,255,0.98);
  backdrop-filter: blur(20px);
  z-index: 200;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
}
.mobile-nav.active { display: flex; }
.mobile-nav a { font-size: 24px; font-weight: 600; }
.mobile-nav-close {
  position: absolute;
  top: 20px;
  right: 24px;
  font-size: 28px;
  background: none;
  border: none;
  cursor: pointer;
}

/* ===== HERO ===== */
.hero {
  text-align: center;
  padding: 80px 24px 60px;
  max-width: 800px;
  margin: 0 auto;
}
.hero h1 {
  font-size: clamp(36px, 5.5vw, 64px);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.035em;
  margin-bottom: 20px;
}
.hero p {
  font-size: clamp(16px, 2vw, 19px);
  color: var(--text-secondary);
  max-width: 540px;
  margin: 0 auto 36px;
  line-height: 1.6;
}
.hero-ctas { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  background: var(--accent);
  color: #fff;
  padding: 14px 32px;
  border-radius: var(--radius-pill);
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); }
.btn-secondary {
  background: var(--surface-gray);
  color: var(--primary-dark);
  padding: 14px 32px;
  border-radius: var(--radius-pill);
  font-size: 16px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  border: 1px solid var(--mid-gray);
}
.btn-secondary:hover { background: var(--mid-gray); transform: translateY(-1px); }

/* ===== TRUSTED BY ===== */
.trusted-by {
  padding: 40px 0 60px;
  text-align: center;
}
.trusted-by p {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 28px;
}
.trusted-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  padding: 0 24px;
  opacity: 0.45;
}
.trusted-logos span {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

/* ===== STATS ===== */
.stats {
  padding: 80px 0;
  background: var(--surface-gray);
}
.stats-label {
  text-align: center;
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 48px;
  font-weight: 500;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 24px;
}
.stat-card {
  text-align: center;
  background: var(--bg-white);
  padding: 40px 24px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.stat-number {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-label {
  font-size: 15px;
  color: var(--text-secondary);
  font-weight: 500;
}

/* ===== FEATURE: SEARCH ===== */
.features-search {
  padding: 100px 0;
}
.section-header {
  text-align: center;
  margin-bottom: 48px;
}
.section-header h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
  line-height: 1.1;
}
.section-header p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 520px;
  margin: 0 auto;
}

.search-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 24px;
  background: var(--surface-gray);
  border-radius: var(--radius-pill);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.search-tab {
  padding: 10px 22px;
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
  white-space: nowrap;
}
.search-tab.active {
  background: var(--bg-white);
  color: var(--primary-dark);
  box-shadow: var(--shadow-sm);
  font-weight: 600;
}
.search-tab:hover:not(.active) { color: var(--primary-dark); }

.filter-pills {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 36px;
  padding: 0 24px;
}
.filter-pill {
  padding: 8px 18px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 500;
  border: 1px solid var(--mid-gray);
  color: var(--text-secondary);
  transition: all var(--transition);
  white-space: nowrap;
}
.filter-pill.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.filter-pill:hover:not(.active) {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-light);
}

.screenshot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}
.screenshot-card {
  background: var(--surface-gray);
  border-radius: var(--radius-md);
  aspect-ratio: 9/16;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.screenshot-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(108,92,231,0.06), rgba(108,92,231,0.02));
}
.screenshot-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.screenshot-card-inner {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.screenshot-card-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--bg-white);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
}
.screenshot-card-lines {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 8px;
}
.screenshot-card-line {
  height: 6px;
  background: rgba(0,0,0,0.06);
  border-radius: 3px;
}
.screenshot-card-line:nth-child(1) { width: 70%; }
.screenshot-card-line:nth-child(2) { width: 100%; }
.screenshot-card-line:nth-child(3) { width: 55%; }
.screenshot-card-line:nth-child(4) { width: 85%; margin-top: 12px; }
.screenshot-card-line:nth-child(5) { width: 60%; }

.tab-content { display: none; }
.tab-content.active { display: block; animation: fadeIn 300ms ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== FEATURE: FLOWS ===== */
.features-flows {
  padding: 100px 0;
  background: var(--surface-gray);
}
.flows-toggle {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 40px;
  background: var(--bg-white);
  border-radius: var(--radius-pill);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.flows-toggle-btn {
  padding: 10px 24px;
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.flows-toggle-btn.active {
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}
.flows-toggle-btn:hover:not(.active) { color: var(--primary-dark); }

.flows-content {
  max-width: 900px;
  margin: 0 auto;
  padding: 0 24px;
}
.flow-view { display: none; }
.flow-view.active { display: block; animation: fadeIn 300ms ease; }
.flow-preview {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
  box-shadow: var(--shadow-sm);
}
.flow-preview-desc {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.6;
}
.flow-screens {
  display: flex;
  gap: 12px;
  justify-content: center;
  align-items: center;
}
.flow-screen {
  width: 80px;
  height: 140px;
  background: var(--surface-gray);
  border-radius: var(--radius-sm);
  position: relative;
  flex-shrink: 0;
}
.flow-arrow {
  color: var(--accent);
  font-size: 20px;
  flex-shrink: 0;
}
.flow-hotspot {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--accent);
  background: var(--accent-light);
  animation: pulse 2s ease infinite;
}
@keyframes pulse {
  0%, 100% { transform: translateX(-50%) scale(1); opacity: 1; }
  50% { transform: translateX(-50%) scale(1.15); opacity: 0.7; }
}

/* ===== FEATURE: TOOLS ===== */
.features-tools {
  padding: 100px 0;
}
.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 24px;
}
.tool-card {
  background: var(--surface-gray);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: transform var(--transition), box-shadow var(--transition);
}
.tool-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.tool-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--accent-light-2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--accent);
}
.tool-icon svg { width: 24px; height: 24px; }
.tool-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}
.tool-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== TESTIMONIALS ===== */
.testimonials {
  padding: 100px 0;
  background: var(--surface-gray);
  overflow: hidden;
}
.testimonials-marquee {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 48px;
}
.marquee-row {
  display: flex;
  gap: 20px;
  width: max-content;
}
.marquee-row-1 { animation: marqueeLeft 45s linear infinite; }
.marquee-row-2 { animation: marqueeRight 50s linear infinite; }
@keyframes marqueeLeft {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes marqueeRight {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}
.testimonial-card {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 28px;
  min-width: 380px;
  max-width: 420px;
  flex-shrink: 0;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition);
}
.testimonial-card:hover { transform: translateY(-2px); }
.testimonial-text {
  font-size: 14px;
  line-height: 1.65;
  color: var(--primary-dark);
  margin-bottom: 20px;
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}
.testimonial-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-light-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 15px;
  color: var(--accent);
  flex-shrink: 0;
}
.testimonial-name {
  font-size: 14px;
  font-weight: 600;
}
.testimonial-company {
  font-size: 13px;
  color: var(--text-tertiary);
}

/* ===== CTA ===== */
.cta-section {
  padding: 100px 0 60px;
  text-align: center;
}
.cta-section h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
  line-height: 1.1;
}
.cta-section > .container > p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 480px;
  margin: 0 auto 36px;
}
.cta-buttons { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; margin-bottom: 60px; }

.brand-marquee-wrapper { overflow: hidden; padding: 20px 0; }
.brand-marquee-row {
  display: flex;
  gap: 24px;
  width: max-content;
  padding: 10px 0;
}
.brand-marquee-row-1 { animation: marqueeLeft 40s linear infinite; }
.brand-marquee-row-2 { animation: marqueeRight 40s linear infinite; }
.brand-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--surface-gray);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  flex-shrink: 0;
  transition: transform var(--transition);
}
.brand-icon:hover { transform: scale(1.1); }

/* ===== FOOTER ===== */
.footer {
  background: var(--primary-dark);
  color: #fff;
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand p {
  font-size: 14px;
  color: rgba(255,255,255,0.5);
  line-height: 1.6;
  margin-top: 16px;
}
.footer h4 {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
  color: rgba(255,255,255,0.4);
}
.footer-links { display: flex; flex-direction: column; gap: 10px; }
.footer-links a {
  font-size: 14px;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition);
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom span {
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: rgba(255,255,255,0.7); }

/* ===== RESPONSIVE ===== */
@media (max-width: 900px) {
  .stats-grid { grid-template-columns: 1fr; max-width: 360px; }
  .tools-grid { grid-template-columns: 1fr; max-width: 440px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .screenshot-grid { grid-template-columns: repeat(2, 1fr); }
  .search-tabs { overflow-x: auto; width: calc(100% - 48px); justify-content: flex-start; }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: flex; }
  .hero { padding: 48px 24px 40px; }
  .hero h1 { font-size: 36px; }
  .stats, .features-search, .features-flows, .features-tools, .testimonials, .cta-section { padding: 64px 0; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .testimonial-card { min-width: 300px; max-width: 340px; }
  .flow-screens { flex-wrap: wrap; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .filter-pills { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
}
@media (max-width: 480px) {
  .screenshot-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .btn-primary, .btn-secondary { width: 100%; max-width: 280px; justify-content: center; text-align: center; }
}
</style>
</head>
<body>

<!-- Announcement Bar -->
<div class="announcement-bar">
  <span>&#9733;</span> 2025 ScreenVault Awards — Celebrating the best on the internet.
</div>

<!-- Header -->
<header class="header">
  <div class="header-inner">
    <a href="#" class="logo">
      <div class="logo-icon">
        <svg viewBox="0 0 16 16" fill="none"><rect x="2" y="3" width="12" height="10" rx="2" stroke="#fff" stroke-width="1.5"/><path d="M5 7h6M5 9.5h4" stroke="#fff" stroke-width="1.2" stroke-linecap="round"/></svg>
      </div>
      ScreenVault
    </a>
    <nav class="nav-links">
      <a href="#">Pricing</a>
      <a href="#">Awards</a>
      <a href="#">Log in</a>
      <a href="#" class="nav-cta">Join for free</a>
    </nav>
    <button class="mobile-menu-btn" onclick="document.querySelector('.mobile-nav').classList.add('active')" aria-label="Open menu">
      <span></span><span></span><span></span>
    </button>
  </div>
</header>

<!-- Mobile Nav -->
<div class="mobile-nav">
