<script>
(function() {
  // ===== STAT COUNTER ANIMATION =====
  const statsSection = document.getElementById('stats');
  const statNumbers = document.querySelectorAll('.stat-number');
  let statsCounted = false;

  function formatNumber(n) {
    return n.toLocaleString();
  }

  function animateCounter(el, target, duration) {
    const start = performance.now();
    const easeOut = t => 1 - Math.pow(1 - t, 3);

    function update(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      const value = Math.round(easeOut(progress) * target);
      el.textContent = formatNumber(value);
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  const statsObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting && !statsCounted) {
        statsCounted = true;
        statNumbers.forEach(function(el, i) {
          const target = parseInt(el.dataset.target);
          setTimeout(function() {
            animateCounter(el, target, 2000);
          }, i * 200);
        });
      }
    });
  }, { threshold: 0.3 });
  statsObserver.observe(statsSection);

  // ===== SEARCH TABS =====
  const searchTabs = document.querySelectorAll('.search-tab');
  const tabContents = document.querySelectorAll('.tab-content');
  const tabMap = { screens: 'tab-screens', elements: 'tab-elements', flows: 'tab-flows', text: 'tab-text' };

  searchTabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      searchTabs.forEach(function(t) { t.classList.remove('active'); });
      tab.classList.add('active');
      tabContents.forEach(function(c) { c.classList.remove('active'); });
      document.getElementById(tabMap[tab.dataset.tab]).classList.add('active');
    });
  });

  // ===== FILTER PILLS =====
  const filterPills = document.querySelectorAll('.filter-pill');
  filterPills.forEach(function(pill) {
    pill.addEventListener('click', function() {
      filterPills.forEach(function(p) { p.classList.remove('active'); });
      pill.classList.add('active');
      regenerateCards();
    });
  });

  // ===== GENERATE SCREENSHOT CARDS =====
  var cardColors = [
    ['#e8e4ff','#f0ecff'],
    ['#e4ecff','#ecf0ff'],
    ['#e4fff0','#ecffec'],
    ['#fff4e4','#fff8ec'],
    ['#ffe4e8','#ffecf0'],
    ['#e4f8ff','#ecfaff'],
    ['#f5e4ff','#f8ecff'],
    ['#fff9e4','#fffcec']
  ];

  function createCard(idx) {
    var pair = cardColors[idx % cardColors.length];
    var card = document.createElement('div');
    card.className = 'screenshot-card';
    card.innerHTML =
      '<div class="screenshot-card-inner" style="background:linear-gradient(135deg,' + pair[0] + ',' + pair[1] + ')">' +
        '<div class="screenshot-card-icon"><svg width="18" height="18" viewBox="0 0 18 18" fill="none"><rect x="2" y="3" width="14" height="12" rx="2" stroke="#6C5CE7" stroke-width="1.3"/><circle cx="9" cy="9" r="2" stroke="#6C5CE7" stroke-width="1.2"/></svg></div>' +
        '<div class="screenshot-card-lines"><div class="screenshot-card-line"></div><div class="screenshot-card-line"></div><div class="screenshot-card-line"></div><div class="screenshot-card-line"></div><div class="screenshot-card-line"></div></div>' +
      '</div>';
    return card;
  }

  function populateGrid(gridId, count) {
    var grid = document.getElementById(gridId);
    grid.innerHTML = '';
    for (var i = 0; i < count; i++) {
      grid.appendChild(createCard(i));
    }
  }

  function regenerateCards() {
    populateGrid('grid-screens', 8);
    populateGrid('grid-elements', 8);
    populateGrid('grid-flows', 8);
    populateGrid('grid-text', 8);
  }
  regenerateCards();

  // ===== FLOWS TOGGLE =====
  var flowBtns = document.querySelectorAll('.flows-toggle-btn');
  var flowViews = document.querySelectorAll('.flow-view');
  var flowMap = { videos: 'flow-videos', prototype: 'flow-prototype' };

  flowBtns.forEach(function(btn) {
